/* Standalone interaction prototype. No network services or credentials are used. */
const $ = (s) => document.querySelector(s);
const escapeHTML = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed = [
{id:'biology',title:'Cell foundations',category:'Biology',type:'PDF',source:'cell-foundations.pdf',questions:[{prompt:'What is the primary function of ribosomes?',choices:['Protein synthesis','Lipid storage','DNA replication','ATP production'],answer:0},{prompt:'Which organelle produces most of a cell’s ATP?',choices:['Nucleus','Mitochondrion','Golgi apparatus','Ribosome'],answer:1},{prompt:'What molecule carries genetic information?',choices:['Glucose','ATP','DNA','Starch'],answer:2},{prompt:'Which structure controls what enters and leaves a cell?',choices:['Cell membrane','Nucleolus','Chromosome','Cytoplasm'],answer:0},{prompt:'Where does photosynthesis take place in plant cells?',choices:['Ribosomes','Mitochondria','Nucleus','Chloroplasts'],answer:3}]},
{id:'chemistry',title:'Bonding basics',category:'Chemistry',type:'DOCX',source:'bonding-basics.docx',questions:[{prompt:'What is shared in a covalent bond?',choices:['Protons','Electrons','Neutrons','Nuclei'],answer:1},{prompt:'An ionic bond forms through attraction between…',choices:['Oppositely charged ions','Two neutrons','Identical charges','Two nuclei only'],answer:0},{prompt:'Which molecule contains a polar covalent bond?',choices:['H₂','O₂','HCl','N₂'],answer:2},{prompt:'What is the charge of an electron?',choices:['Positive','Neutral','Variable','Negative'],answer:3},{prompt:'Which substance has metallic bonding?',choices:['Water','Copper','Methane','Oxygen'],answer:1}]},
{id:'history',title:'The Renaissance',category:'History',type:'TXT',source:'renaissance-notes.txt',questions:[{prompt:'Where did the European Renaissance begin?',choices:['Italy','Norway','Russia','Ireland'],answer:0},{prompt:'Which artist painted the Mona Lisa?',choices:['Raphael','Leonardo da Vinci','Botticelli','Donatello'],answer:1},{prompt:'Which invention helped spread Renaissance ideas?',choices:['Steam engine','Telephone','Printing press','Telegraph'],answer:2},{prompt:'Renaissance humanism emphasized the study of…',choices:['Classical texts and human experience','Only military tactics','Industrial machinery','Space exploration'],answer:0},{prompt:'Which family was a major patron of the arts in Florence?',choices:['Tudor','Medici','Romanov','Bourbon'],answer:1}]}
];
let stored;try{stored=JSON.parse(localStorage.getItem('quiz-clash-prototype')||'null');}catch{/* Storage can be unavailable for local files. */}
let quizzes=[...seed,...(Array.isArray(stored?.quizzes)?stored.quizzes.filter(q=>q.id&&q.title&&Array.isArray(q.questions)&&q.questions.length&&q.questions.every(x=>typeof x.prompt==='string'&&Array.isArray(x.choices)&&x.choices.length===4&&Number.isInteger(x.answer)&&x.answer>=0&&x.answer<4)):[])];
let history=Array.isArray(stored?.history)?stored.history.filter(h=>typeof h.title==='string'&&Number.isFinite(h.score)&&Number.isFinite(h.total)&&h.total>0):[];
let attempt=null, upload=null, roomQuiz='biology', exportKind='questions', toastTimer, generationTimer;
function save(){try{localStorage.setItem('quiz-clash-prototype',JSON.stringify({quizzes:quizzes.filter(q=>!seed.some(s=>s.id===q.id)),history}));return true;}catch{return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
const icon = (file) => `<img class="icon" src="assets/${file}.svg" alt="">`;
function subjectIcon(q){return q.category==='Chemistry'?'e1edd':q.category==='History'?'e1c9c':'c96d6';}
function studyTip(){return `<section class="study-tip">${icon('04abb')}<span class="eyebrow">MAKE IT STICK</span><h3>Recall first. Review second.</h3><p>Try a solo round before looking at your answer key. Use the questions you miss to guide your next study session.</p><span class="tip-accent"></span></section>`;}
function joinPanel(){return `<form class="panel join-panel" data-join-form><h2>Got a room PIN?</h2><p>Join your study group for a live clash.</p><label for="dashboard-pin">Room PIN</label><input id="dashboard-pin" name="pin" inputmode="numeric" placeholder="482 916" maxlength="7" required><p class="error" data-pin-error role="alert"></p><button class="button primary wide" type="submit">${icon('66839')} Join room</button><p class="hint">Demo PIN: 482 916. A PIN lets you play, not access the host’s source files or answer keys.</p></form>`;}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
const createButton='<a class="button primary" href="#create"><img class="icon" src="assets/e1d4d.svg" alt=""> Create a quiz</a>';
function card(q){return `<article class="quiz-card ${q.id==='biology'?'featured':''}"><div class="card-identity"><span class="subject-icon">${icon(subjectIcon(q))}</span><button class="icon-button" data-action="quiz-menu" data-id="${q.id}" aria-label="Options for ${escapeHTML(q.title)}">${icon('bd472')}</button></div><div class="card-body"><span class="tag">${escapeHTML(q.category)}</span><h3><a href="#quiz/${encodeURIComponent(q.id)}">${escapeHTML(q.title)}</a></h3><p>${q.questions.length} questions · ${escapeHTML(q.type)}</p></div><div class="card-bottom"><span>${seed.includes(q)?'Sample quiz':'Created by you'}</span><a href="#quiz/${encodeURIComponent(q.id)}">Open quiz ${icon('526d9')}</a></div></article>`;}
function activity(){const soloHistory=history.filter(h=>h.mode==='Solo practice');if(!soloHistory.length)return '<div class="empty-activity"><h3>Your next chapter starts here.</h3><p>Complete a solo quiz to see your progress in this space.</p><a class="text-link" href="#quiz/biology">Try Cell foundations →</a></div>';return soloHistory.slice(0,3).map(h=>`<a href="#history" class="activity">${icon('298ad')}<span class="activity-title">${escapeHTML(h.title)}</span><time>${new Date(h.date).toLocaleDateString()}</time><span>${h.score} / ${h.total}</span><b class="status">${Math.round(h.score/h.total*100)}%</b>${icon('55a48')}</a>`).join('');}
function dashboard(){const last=history.find(h=>h.title==='Cell foundations'&&h.mode==='Solo practice');return heading('Good afternoon, Alex.','A fresh question is a good place to start.',createButton)+`<div class="dashboard-columns"><div class="quiz-workspace"><section class="continue-banner"><span class="study-icon">${icon('550c0')}</span><div><span class="eyebrow">KEEP YOUR MOMENTUM</span><h2>Cell foundations, stronger recall.</h2><p>${last?'Your latest session: '+last.score+' of '+last.total+' correct. Ready for another round?':'Build your recall, one question at a time. Ready for a round?'}</p></div><button class="button" data-action="start" data-id="biology">${icon('e4ac2')} ${last?'Practice again':'Start practice'}</button></section><section><div class="section-heading"><div><h2>My quizzes</h2><span class="count-badge">${quizzes.length} quizzes</span></div><label class="sort-control"> <span class="visually-hidden">Sort quizzes</span><select id="dashboard-sort"><option value="recent">Recently updated</option><option value="title">Name A–Z</option></select>${icon('fffd2')}</label></div><div class="quiz-grid" id="dashboard-grid">${quizzes.slice(0,3).map(card).join('')}</div>${quizzes.length>3?'<a class="text-link" href="#library">View all quizzes →</a>':''}</section><section class="panel recent-panel"><h2>Recent solo activity</h2>${activity()}</section></div><aside class="study-sidebar">${joinPanel()}${studyTip()}</aside></div>`;}
function library(){return heading('Your quiz library','A home for everything you’re learning.',createButton)+`<div class="toolbar"><label class="visually-hidden" for="search">Search quizzes</label><input id="search" type="search" placeholder="Search your quizzes…"><label class="visually-hidden" for="filter">Filter category</label><select id="filter" style="width:auto"><option value="">All subjects</option>Languages</option>Development</option>Science</option>My uploads</option></select></div><div class="quiz-grid" id="library-grid">${quizzes.map(card).join('')}</div>`;}
function create(){return heading('Make your notes work for you.','Upload your study material. Leave with a new way to learn.')+`<div class="form-grid"><form id="create-form" class="panel"><span class="eyebrow">01 / YOUR STUDY MATERIAL</span><label class="dropzone" id="dropzone" for="file"><span class="upload-icon">↥</span><strong id="file-name">Drop your notes here</strong><p>or click to browse your files</p><span class="format-pills"><span>PDF</span><span>DOCX</span><span>CSV</span><span>TXT</span></span></label><input class="visually-hidden" id="file" type="file" accept=".pdf,.docx,.csv,.txt" aria-describedby="upload-hint"><p class="hint" id="upload-hint">Up to 10 MB per file · Prototype limit</p><p id="upload-error" class="error" role="alert"></p><button class="button ghost" type="button" data-action="sample">Try a sample file ↗</button><label for="quiz-title">Quiz name</label><input id="quiz-title" required maxlength="80" placeholder="e.g. Cell biology — week 1"><label for="question-count">Number of questions</label><select id="question-count"><option value="3">3 questions · A quick check-in</option><option value="5" selected>5 questions · A little practice</option></select><p class="hint">Demo generation uses a curated cell biology set. Your uploaded file is selected locally, but its content is not parsed or sent anywhere.</p><button id="generate" class="button primary wide" type="submit">Generate demo quiz <span>✧</span></button><p id="generation-status" class="hint" role="status"></p></form><aside><section class="panel"><span class="eyebrow">A SMALL STEP TO BETTER RECALL</span><h2 style="margin-top:16px">Your notes, reimagined.</h2><div class="steps"><div class="step"><h3>Bring what you’re learning</h3><p>Vocabulary, lecture notes, or that topic you want to finally understand.</p></div><div class="step"><h3>Review your questions</h3><p>Check your generated study set before jumping into practice.</p></div><div class="step"><h3>Find your way to study</h3><p>Go solo, print a worksheet, or challenge your friends.</p></div></div></section><p class="hint">Designed for selectable text. Scanned PDFs would need OCR, which is outside the initial project scope.</p></aside></div>`;}
function detail(q){return heading(escapeHTML(q.title),`${escapeHTML(q.source)} · ${q.questions.length} questions · ${escapeHTML(q.category)}`,'<a href="#library" class="button">← My quizzes</a>')+`<div class="notice">${seed.includes(q)?'Sample quiz':'Demo-generated quiz'} · Review these questions before studying. AI-generated content in the planned app will also need review.</div><div class="mode-grid"><section class="panel"><span class="stat-icon">◎</span><h3>Your pace. Your progress.</h3><p>Practice one question at a time and see what you remember.</p><button class="button primary" data-action="start" data-id="${q.id}">Start solo practice →</button></section><section class="panel"><span class="stat-icon">⚡</span><h3>Make it a friendly clash.</h3><p>Explore the room, questions, and standings with a simulated opponent.</p><button class="button" data-action="host" data-id="${q.id}">Host a demo clash ↗</button></section><section class="panel"><span class="stat-icon">↧</span><h3>Take your learning offline.</h3><p>Prepare a question sheet or a separate answer key for printing.</p><a class="button" href="#export/${q.id}">Prepare study sheets ↗</a></section></div><section class="panel"><div class="section-heading" style="margin-top:0"><h2>A peek inside</h2><span class="tag">${q.questions.length} QUESTIONS</span></div>${q.questions.map((x,i)=>`<div class="question-preview"><h3>${i+1}. ${escapeHTML(x.prompt)}</h3><p>${x.choices.map((c,j)=>`${'ABCD'[j]}. ${escapeHTML(c)}`).join(' &nbsp; · &nbsp; ')}</p></div>`).join('')}</section>`;}
function battle(){return heading('Learning is better together.','Turn a study session into a little friendly competition.')+`<div class="notice">Multiplayer preview · Rooms and opponents are simulated on this device. No live connection is created.</div><div class="form-grid"><section class="panel"><span class="eyebrow">YOU SET THE CHALLENGE</span><h2 style="margin:18px 0">Host a clash</h2><p>Pick a quiz, open your room, and get ready for a shared challenge.</p><label for="host-quiz">Choose a quiz</label><select id="host-quiz">${quizzes.map(q=>`<option value="${q.id}" ${q.id===roomQuiz?'selected':''}>${escapeHTML(q.title)}</option>`).join('')}</select><div class="actions"><button class="button primary" data-action="host-selected">Create demo room ↗</button></div></section><section class="panel"><span class="eyebrow">ALREADY HAVE A PIN?</span><h2 style="margin:18px 0">Join the fun.</h2><p>Explore the player’s side of a clash with demo PIN <strong>482 916</strong>.</p><button class="button" data-action="join">Enter a room PIN →</button></section></div>`;}
function lobby(joined=false){const q=quizzes.find(q=>q.id===roomQuiz)||seed[0];return heading(joined?'You’re in. Get ready.':'Better together. A little competitive.','Invite your study group, then start the clash when everyone is here.','<a class="button" href="#battle">Close room</a>')+`<div class="lobby-columns"><div class="host-controls"><section class="room-invitation"><span class="eyebrow"><span class="status-dot"></span> DEMO ROOM OPEN · WAITING TO START</span><p>Join with this room PIN</p><div class="room-pin">482 916</div><button class="button copy-pin" data-action="copy-pin">${icon('d938a')} Copy room PIN</button><p class="invitation-note">Players enter this PIN in “Join room” in Quiz Clash. This prototype simulates players locally; it does not connect devices.</p></section><section class="panel host-settings"><div class="quiz-identity">${icon('eadfb')}<strong>${escapeHTML(q.category)} · ${escapeHTML(q.title)}</strong><span>${q.questions.length} questions</span></div><div class="round-info"><span>${icon('25b25')} ${q.questions.length} shared questions</span><span>${icon('a6eea')} Untimed demo</span></div><button class="button primary wide" data-action="start-battle">${icon('b6700')} ${joined?'Preview live quiz':'Start demo quiz'}</button><p class="hint">${joined?'You joined the local demo. Advance when you’re ready.':'You’re the host. Only you can start this room.'}</p></section></div><div class="lobby-participants"><section class="panel"><div class="section-heading"><h2>The study group</h2><span class="status">2 joined</span></div><div class="player"><span class="avatar">AM</span><div><strong>Alex Morgan</strong><small>You · ${joined?'Player':'Host'}</small></div>${joined?'<span class="status">Ready</span>':icon('23ef2')}</div><div class="player"><span class="avatar neutral">MC</span><div><strong>Maya Chen</strong><small>Demo opponent · ${joined?'Host':'Ready to play'}</small></div>${joined?icon('23ef2'):`<span class="status">${icon('1e22c')} Ready</span>`}</div><div class="waiting">${icon('c614d')} The demo group is waiting for you to start.</div></section><section class="guidance">${icon('ff6be')}<div><strong>A PIN is an invitation to play</strong><p>Joining a room does not give players access to your study file, quiz library or answer key.</p></div></section><section class="reconnect">${icon('b6c51')}<div><strong>A dropped connection doesn’t have to end the game.</strong><p>The planned live version will let players rejoin a room. This local demo uses 100 points per correct answer.</p></div></section></div></div>`;}
function play(){if(!attempt){location.hash='library';return '';}const q=attempt.quiz.questions[attempt.index],total=attempt.quiz.questions.length;return heading(attempt.battle?'A little friendly competition.':'A little focus goes a long way.','', '<button class="button" data-action="exit">Leave practice</button>')+`<div class="practice-columns"><div class="question-workspace"><div class="progress-meta"><div class="quiz-identity">${icon('eadfb')}<strong>${escapeHTML(attempt.quiz.category)} · ${escapeHTML(attempt.quiz.title)}</strong><span>${total} questions</span></div><span>Question ${attempt.index+1} of ${total}</span></div><div class="segmented-progress" aria-label="Question ${attempt.index+1} of ${total}">${attempt.quiz.questions.map((_,i)=>`<span class="${i<=attempt.index?'filled':''}"></span>`).join('')}</div><section class="panel question-panel"><div class="question-heading"><span class="eyebrow">QUESTION ${String(attempt.index+1).padStart(2,'0')}</span><span class="count-badge">${escapeHTML(attempt.quiz.category)}</span></div><h2>${escapeHTML(q.prompt)}</h2><p>Choose one answer, then submit when you’re ready.</p><div class="options">${q.choices.map((c,i)=>`<button class="option ${attempt.checked?(i===q.answer?'correct':i===attempt.selected?'wrong':''):i===attempt.selected?'selected':''}" data-action="answer" data-index="${i}" aria-pressed="${i===attempt.selected}" ${attempt.checked?'disabled':''}><span class="choice-letter">${'ABCD'[i]}</span><span class="choice-text">${escapeHTML(c)}</span>${i===attempt.selected?`<small>Selected</small>${icon('c1d8f')}`:''}</button>`).join('')}</div>${attempt.checked?`<div class="feedback" role="status"><strong>${attempt.selected===q.answer?'You’ve got it.':'A new thing to remember.'}</strong> The correct answer is ${escapeHTML(q.choices[q.answer])}.${attempt.battle?`<br>Maya (demo): ${botScore()} points · You: ${attempt.score*100} points`:''}</div>`:''}<div class="answer-submission"><span>${icon('84be1')} ${attempt.checked?'Answer checked':attempt.selected===null?'Choose an answer to continue':'Answer selected · Not yet graded'}</span><button class="button primary" data-action="${attempt.checked?'next':'check'}" ${attempt.selected===null?'disabled':''}>${icon('66839')} ${attempt.checked?(attempt.index===total-1?'See my results':'Next question'):'Submit answer'}</button></div></section></div><aside class="practice-sidebar"><section class="panel"><h2>Your session</h2><div class="session-count"><strong>${attempt.answers.length}</strong><span>/ ${total} submitted</span></div><div class="question-map">${attempt.quiz.questions.map((_,i)=>`<span class="${i===attempt.index?'current':i<attempt.index?'submitted':''}">${String(i+1).padStart(2,'0')}</span>`).join('')}</div><p class="hint legend">■ Current question</p></section><section class="practice-reassurance">${icon('15b31')}<h3>No clock. Just curiosity.</h3><p>Take your time. Your answers are checked after submission, and your completed attempt is saved to history.</p></section></aside></div>`;}
function botScore(){return Math.floor((attempt.index+1)*.7)*100;}
function results(){if(!attempt?.completed){location.hash='history';return '';}const pct=Math.round(attempt.score/attempt.quiz.questions.length*100);return `<div class="quiz-stage"><section class="panel result"><span class="eyebrow">${attempt.battle?'DEMO CLASH COMPLETE':'SESSION COMPLETE'}</span><h1 style="margin-top:20px">A little more learned.</h1><p>${escapeHTML(attempt.quiz.title)}</p><div class="score-ring"><strong>${pct}%</strong><span>accuracy</span></div><h2>${attempt.score} of ${attempt.quiz.questions.length} correct</h2><p>${pct===100?'That’s a clean sweep. Keep your curiosity going.':'Every attempt helps it stick. Review your answers and try again.'}</p>${attempt.battle?`<div class="notice">Final demo standings: ${attempt.score*100>=botScore()?'1. You · '+attempt.score*100+' pts &nbsp; 2. Maya · '+botScore()+' pts':'1. Maya · '+botScore()+' pts &nbsp; 2. You · '+attempt.score*100+' pts'}</div>`:''}<div class="actions"><button class="button primary" data-action="start" data-id="${attempt.quiz.id}">Practice again ↻</button><a class="button" href="#history">View study history</a></div></section><section class="panel" style="margin-top:22px"><h2>Your answer review</h2>${attempt.quiz.questions.map((q,i)=>`<div class="question-preview"><h3>${attempt.answers[i]===q.answer?'✓':'○'} ${escapeHTML(q.prompt)}</h3><p>Your answer: ${escapeHTML(q.choices[attempt.answers[i]])}<br>Correct answer: ${escapeHTML(q.choices[q.answer])}</p></div>`).join('')}</section></div>`;}
function historyPage(){return heading('See how far you’ve come.','Every session is another step toward knowing it by heart.')+`<section class="panel">${history.length?`<div class="table-wrap"><table><thead><tr><th>Quiz</th><th>Mode</th><th>Accuracy</th><th>Completed</th></tr></thead><tbody>${history.map(h=>`<tr><td>${escapeHTML(h.title)}</td><td>${escapeHTML(h.mode)}</td><td><span class="status">${Math.round(h.score/h.total*100)}% · ${h.score}/${h.total}</span></td><td>${new Date(h.date).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><span class="upload-icon">◷</span><h2>Your story starts with one quiz.</h2><p>Complete a practice session to see your results here.</p><a class="button primary" href="#library">Find a quiz →</a></div>'}</section><p class="hint">Prototype history is stored in this browser when local storage is available.</p>`;}
function exportPage(q){return heading('A little learning, unplugged.',escapeHTML(q.title))+`<div class="notice">Use your browser’s print dialog to print or save as PDF. Word export is a planned feature; its demo button previews the intended workflow.</div><section class="panel export-controls"><label for="export-kind">Study sheet</label><select id="export-kind"><option value="questions" ${exportKind==='questions'?'selected':''}>Questions only</option><option value="answers" ${exportKind==='answers'?'selected':''}>Separate answer key</option></select><div class="actions"><button class="button primary" data-action="print">Print / Save as PDF ↗</button><button class="button" data-action="word">Preview Word export</button><a class="button" href="#quiz/${q.id}">Back to quiz</a></div></section><article class="export-preview"><span class="eyebrow">QUIZ CLASH / ${exportKind==='answers'?'ANSWER KEY':'STUDY SHEET'}</span><h1 style="margin-top:20px">${escapeHTML(q.title)}</h1>${exportKind==='questions'?'<p>Name: ____________________ &nbsp; Date: ______________</p>':''}<ol>${q.questions.map(q=>`<li><strong>${escapeHTML(q.prompt)}</strong><br>${exportKind==='answers'?`${'ABCD'[q.answer]}. ${escapeHTML(q.choices[q.answer])}`:q.choices.map((c,i)=>`${'ABCD'[i]}. ${escapeHTML(c)}`).join('<br>')}</li>`).join('')}</ol></article>`;}
function render(focus=false){const [page='dashboard',id]=location.hash.slice(1).split('/');const q=quizzes.find(q=>q.id===id);const titles={dashboard:'Your workspace',library:'My quizzes',create:'Create a quiz',quiz:'Quiz details',battle:'Live clash',lobby:'Demo lobby',joined:'Join a clash',play:'Practice',results:'Results',history:'Study history',export:'Offline study'};$('#breadcrumb').textContent=page==='dashboard'||!page?'YOUR WORKSPACE':'MY QUIZZES / '+(titles[page]||'Your workspace').toUpperCase();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(a.dataset.nav==='dashboard'&&['','library','quiz','create','export','play','results','battle','lobby','joined'].includes(page))||(a.dataset.nav==='library'&&['quiz','create','export','play','results'].includes(page))||(a.dataset.nav==='battle'&&['lobby','joined'].includes(page));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.body.dataset.page=page||'dashboard';const livePage=['lobby','joined','play'].includes(page);$('.header-join').hidden=livePage;$('#header-status').hidden=!livePage;$('#header-status').innerHTML=icon('6b67d')+' '+(page==='play'?(attempt?.battle?'Demo clash':'Solo practice'):'Demo room');const views={dashboard,library,create,battle,lobby:()=>lobby(),joined:()=>lobby(true),play,results,history:historyPage,quiz:()=>q?detail(q):library(),export:()=>q?exportPage(q):library()};$('#main').innerHTML=(views[page]||dashboard)();if(page==='create')setupUpload();if($('#dashboard-sort'))$('#dashboard-sort').addEventListener('change',()=>{$('#dashboard-grid').innerHTML=($('#dashboard-sort').value==='title'?[...quizzes].sort((a,b)=>a.title.localeCompare(b.title)):[...quizzes].reverse()).slice(0,3).map(card).join('');});if(page==='library'){for(const el of [$('#search'),$('#filter')])el.addEventListener('input',()=>{const matches=quizzes.filter(q=>q.title.toLowerCase().includes($('#search').value.toLowerCase())&&(!$('#filter').value||q.category===$('#filter').value));$('#library-grid').innerHTML=matches.length?matches.map(card).join(''):'<div class="panel empty">No matching quizzes. Try another search or subject.</div>';});}if(focus){$('#main').focus();window.scrollTo(0,0);}}
function modal(title,content){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${content}`;$('#dialog').showModal();}
function setupUpload(){upload=null;const file=$('#file'),zone=$('#dropzone');file.addEventListener('change',()=>selectFile(file.files[0]));zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');selectFile(e.dataTransfer.files[0]);});$('#create-form').addEventListener('submit',e=>{e.preventDefault();if(!upload){$('#upload-error').textContent='Choose a supported file, or try the sample file.';return;}const title=$('#quiz-title').value.trim();if(!title){$('#quiz-title').setCustomValidity('Enter a quiz name.');$('#quiz-title').reportValidity();return;}const count=Number($('#question-count').value),source=upload.name;$('#generate').disabled=true;$('#generate').textContent='Preparing your demo quiz…';$('#generation-status').textContent='Preparing sample questions and answer choices…';generationTimer=setTimeout(()=>{const q={...seed[0],id:'quiz-'+Date.now(),title,category:'My uploads',source,type:source.split('.').pop().toUpperCase(),questions:seed[0].questions.slice(0,count)};quizzes.push(q);const saved=save();location.hash='quiz/'+q.id;toast(saved?'Your demo quiz is ready.':'Quiz is ready for this visit. Browser storage is unavailable.');},900);});$('#quiz-title').addEventListener('input',()=>$('#quiz-title').setCustomValidity(''));}
function selectFile(file){upload=null;$('#file-name').textContent='Drop your notes here';let error='';if(!file)error='Choose a file to continue.';else if(!/\.(pdf|docx|csv|txt)$/i.test(file.name))error='Use a PDF, DOCX, CSV, or TXT file.';else if(file.size===0)error='This file is empty. Choose a file with study material.';else if(file.size>10*1024*1024)error='This file is over 10 MB. Choose a smaller file.';$('#upload-error').textContent=error;if(error)return;upload=file;$('#file-name').textContent=file.name;$('#quiz-title').value=file.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ').slice(0,80);$('#quiz-title').setCustomValidity('');}
function start(id,battle=false){const quiz=quizzes.find(q=>q.id===id)||seed[0];attempt={quiz,index:0,score:0,selected:null,checked:false,answers:[],battle,completed:false};if(location.hash==='#play')render();else location.hash='play';}
document.addEventListener('change',e=>{if(e.target.id==='export-kind'){exportKind=e.target.value;render();$('#export-kind').focus();}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;switch(action){case'quiz-menu':{const q=quizzes.find(q=>q.id===target.dataset.id);modal(escapeHTML(q.title),`<div class="actions"><button class="button primary" data-action="start" data-id="${q.id}">Start practice</button><button class="button" data-action="host" data-id="${q.id}">Host demo clash</button><a class="button" href="#export/${q.id}">Study sheets</a></div>`);break;}case'copy-pin':navigator.clipboard?.writeText('482916').then(()=>toast('Room PIN copied.')).catch(()=>toast('Room PIN: 482 916'));if(!navigator.clipboard)toast('Room PIN: 482 916');break;case'close':$('#dialog').close();break;case'profile':modal('Your personal workspace','<p>You’re exploring as Alex Morgan, a demo learner. Sign-in and account creation will link quizzes and history in the full application.</p><div class="notice">No password or personal information is needed for this prototype.</div><button class="button primary wide" data-action="close">Continue exploring</button>');break;case'join':modal('Join a clash','<p>Enter the demo room PIN to preview the player experience.</p><form id="join-form"><label for="pin">Room PIN</label><input id="pin" inputmode="numeric" autocomplete="off" placeholder="482916" maxlength="7" required><p id="pin-error" class="error" role="alert"></p><p class="hint">Try 482916 · Local simulation only</p><button class="button primary wide" type="submit">Join demo room →</button></form>');$('#join-form').addEventListener('submit',e=>{e.preventDefault();if($('#pin').value.replace(/\s/g,'')!=='482916'){$('#pin-error').textContent='Room not found. Use the demo PIN 482916.';return;}roomQuiz='biology';$('#dialog').close();location.hash='joined';});break;case'sample':selectFile({name:'cell-foundations.csv',size:428});break;case'host':roomQuiz=target.dataset.id;location.hash='lobby';break;case'host-selected':roomQuiz=$('#host-quiz').value;location.hash='lobby';break;case'start-battle':start(roomQuiz,true);break;case'start':start(target.dataset.id);break;case'answer':if(attempt&&!attempt.checked){attempt.selected=Number(target.dataset.index);render();document.querySelector(`[data-index="${attempt.selected}"]`).focus();}break;case'check':if(!attempt||attempt.checked||attempt.selected===null)return;attempt.checked=true;attempt.answers.push(attempt.selected);if(attempt.selected===attempt.quiz.questions[attempt.index].answer)attempt.score++;render();document.querySelector('[data-action="next"]').focus();break;case'next':if(!attempt?.checked||attempt.completed)return;if(attempt.index<attempt.quiz.questions.length-1){attempt.index++;attempt.selected=null;attempt.checked=false;render(true);}else{attempt.completed=true;history.unshift({title:attempt.quiz.title,score:attempt.score,total:attempt.quiz.questions.length,date:new Date().toISOString(),mode:attempt.battle?'Demo clash':'Solo practice'});if(!save())toast('Session complete. Browser storage is unavailable.');location.hash='results';}break;case'exit':modal('Leave this practice session?','<p>Your answers in this unfinished session won’t be saved.</p><div class="actions"><button class="button primary" data-action="close">Keep practicing</button><button class="button" data-action="confirm-exit">Leave session</button></div>');break;case'confirm-exit':$('#dialog').close();attempt=null;location.hash='library';break;case'print':window.print();break;case'word':modal('Your Word export preview','<p>The full app will download a .docx study sheet with the selected questions or answer key.</p><div class="notice">This prototype previews the sheet on screen. Use Print / Save as PDF for a working offline copy.</div><button class="button primary wide" data-action="close">Back to study sheet</button>');break;}});
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();clearTimeout(generationTimer);render(true);});render();
// Focus the current view without treating the skip link as an application route.
document.querySelector('.skip').addEventListener('click', e => { e.preventDefault(); $('#main').focus(); });

document.addEventListener('submit',e=>{if(!e.target.matches('[data-join-form]'))return;e.preventDefault();const form=e.target;const pin=new FormData(form).get('pin').replace(/\s/g,'');if(pin!=='482916'){form.querySelector('[data-pin-error]').textContent='Room not found. Try demo PIN 482 916.';return;}roomQuiz='biology';location.hash='joined';});
